"""Write docs/review/<book>-lexemes.md: one row per lexeme the app shows, for content reviewers.

Usage: python pipeline/review_packet.py Ruth
"""
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent


def main(book: str) -> None:
    text = (ROOT / "data" / f"{book.lower()}.js").read_text(encoding="utf-8")
    d = json.loads(text[text.index("{"): text.rindex("}") + 1])
    toks = {t["id"]: (v, t) for v in d["verses"] for t in v["t"]}
    L = d["lexemes"]
    out = [f"# {book}: every lexeme the app shows (review packet)", "",
           "Generated by pipeline/review_packet.py from data/" + book.lower() + ".js. Columns: key (OSHB augmented Strong's), "
           "headword, part of speech (Lexical Index), shown gloss, raw TBESH gloss, BDB short definition (Lexical Index), "
           "BDB page, count in book, first occurrence (form, reference, parse).", ""]

    def row(k, r):
        first = r["occ"][0] if r.get("occ") else None
        f = ""
        if first:
            v, t = toks[first]
            f = f"{t['p']} ({v['ref']}; {t['parse']})"
        bdb = r.get("bdb") or {}
        return (f"| {k} | {r.get('he', '')} | {r.get('pos', r.get('tm', ''))} | **{r['gloss']}** | {r.get('tg', '')} | "
                f"{r.get('def', '')} | {bdb.get('page', '')} | {r.get('n', 0)} | {f} |")

    head = "| key | Hebrew | pos | shown gloss | TBESH raw | BDB def | BDB p. | n | first occurrence |\n|---|---|---|---|---|---|---|---|---|"
    vocab = sorted((k for k, r in L.items() if not r.get("affix") and not r.get("name")), key=lambda k: -L[k]["n"])
    out += ["## Vocabulary (drilled)", "", head, *[row(k, L[k]) for k in vocab], ""]
    out += ["## Names (own tab, not drilled)", "", head, *[row(k, L[k]) for k in sorted(k for k, r in L.items() if r.get("name"))], ""]
    out += ["## Prefixes and suffixes (glossed from TBESH H9000+ rows)", "", head,
            *[row(k, L[k]) for k in sorted(k for k, r in L.items() if r.get("affix"))], ""]
    out += ["## Written (ketiv) and read (qere) places", "", "| ref | written | read | differs in |", "|---|---|---|---|"]
    for e in d["kq"]:
        k = toks[e["k"]][1] if e["k"] else None
        qs = [toks[q][1] for q in e["q"]]
        ks = f"{k['c']} ({k['parse']}; {L[k['lex']]['gloss']})" if k else "(none)"
        qq = "; ".join(f"{q['p']} ({q['parse']}; {L[q['lex']]['gloss']})" for q in qs) or "(none)"
        out.append(f"| {e['ref']} | {ks} | {qq} | {', '.join(e['diff'])} |")
    dest = ROOT / "docs" / "review" / f"{book.lower()}-lexemes.md"
    dest.parent.mkdir(parents=True, exist_ok=True)
    dest.write_text("\n".join(out) + "\n", encoding="utf-8")
    print(dest.relative_to(ROOT), len(vocab), "vocab rows")


if __name__ == "__main__":
    main(sys.argv[1] if len(sys.argv) > 1 else "Ruth")
